//! Embedded asset source: the icon set ships inside the binary, with
//! gpui-kit's bundled Lucide icon set as the fallback so kit components
//! (Input decorations, popovers, …) can resolve their IconName assets.

use gpui::AssetSource;

// generated by build.rs: static EMBEDDED_FILES: &[(&str, &[u8])]
include!(concat!(env!("OUT_DIR"), "/embedded_assets.rs"));

pub struct EmbedAssets {
    kit: gpui_kit::assets::Assets,
}

impl Default for EmbedAssets {
    fn default() -> Self {
        Self::new()
    }
}

impl EmbedAssets {
    pub fn new() -> Self {
        Self { kit: gpui_kit::assets::Assets }
    }
}

impl AssetSource for EmbedAssets {
    fn load(&self, path: &str) -> anyhow::Result<Option<std::borrow::Cow<'static, [u8]>>> {
        match EMBEDDED_FILES.iter().find(|(name, _)| *name == path) {
            Some((_, data)) => Ok(Some(std::borrow::Cow::Borrowed(*data))),
            None => self.kit.load(path),
        }
    }

    fn list(&self, path: &str) -> anyhow::Result<Vec<gpui::SharedString>> {
        let mut ours: Vec<gpui::SharedString> = EMBEDDED_FILES
            .iter()
            .map(|(name, _)| gpui::SharedString::from(*name))
            .filter(|name| name.starts_with(path))
            .collect();
        let mut kit = self.kit.list(path)?;
        ours.append(&mut kit);
        Ok(ours)
    }
}

#[cfg(test)]
mod tests {
    // regression: on Windows drives where std::fs::canonicalize fails (mapped
    // / subst volumes), rust-embed silently embedded an empty asset set and
    // the UI ran without any icons. These run against the real embed table.
    #[test]
    fn embedded_set_is_populated() {
        assert!(super::EMBEDDED_FILES.len() > 50, "only {} assets embedded", super::EMBEDDED_FILES.len());
    }

    #[test]
    fn embedded_icons_resolve() {
        let (_, data) = super::EMBEDDED_FILES
            .iter()
            .find(|(name, _)| *name == "icons/icon-cog.svg")
            .expect("icons/icon-cog.svg embedded");
        assert!(data.starts_with(b"<svg"), "icon-cog.svg is not an svg");
    }
}
